<script setup>
import {ref,computed} from 'vue';
import FilterChip from './FilterChip.vue';import ViewToggle from './ViewToggle.vue';import AppIcon from './AppIcon.vue';
const props=defineProps({state:Object,categoryOptions:Array,avatarOptions:Array,tagOptions:Array,count:Number,total:Number});const emit=defineEmits(['clear']);const opened=ref('');
const active=computed(()=>props.state.chosenCategories.length||props.state.chosenAvatars.length||props.state.chosenTags.length||props.state.onlyFavorites||props.state.query||!props.state.includeGeneric);
</script>
<template><div class="library-filter-bar"><FilterChip alphabetical label="Categoría" search-label="categoría" :options="categoryOptions" v-model="state.chosenCategories" :open="opened==='category'" @open="opened='category'" @close="opened==='category'&&(opened='')"/><FilterChip label="Avatar" search-label="avatar" :options="avatarOptions" v-model="state.chosenAvatars" avatar v-model:include-generic="state.includeGeneric" :open="opened==='avatar'" @open="opened='avatar'" @close="opened==='avatar'&&(opened='')"/><FilterChip label="Tags" search-label="tag" :options="tagOptions" v-model="state.chosenTags" :open="opened==='tags'" @open="opened='tags'" @close="opened==='tags'&&(opened='')"/><button type="button" class="library-favorites-filter" :class="{selected:state.onlyFavorites}" :aria-pressed="state.onlyFavorites" @click="state.onlyFavorites=!state.onlyFavorites"><AppIcon name="heart" :filled="state.onlyFavorites"/>Favoritos</button><button v-if="active" type="button" class="library-clear-filters" @click="emit('clear')">Limpiar</button><div class="library-filter-spacer"></div><label class="library-sort">Ordenar<select v-model="state.sortBy"><option value="az">Nombre: A → Z</option><option value="za">Nombre: Z → A</option><option value="largest">Tamaño: mayor primero</option><option value="smallest">Tamaño: menor primero</option></select></label><select v-model="state.perPage" class="library-per-page" aria-label="Productos por página"><option v-for="n in ['30','60','90','120','all']" :key="n" :value="n">{{n==='all'?'Todos':n+' por página'}}</option></select><ViewToggle v-model="state.viewMode"/></div></template>